// Raytracing Boilerplate V2 by Bingle
/* Axis orientation (local to camera):

       ^ +Y
       |
       |
       |
       +-------> +X
      /
 +Z |/ 
     ‾‾
*/

float sphereIntersect(ray r, vec3 pos, float rad){
    vec3 oc = pos-r.pos;
    float a = dot(r.dir,r.dir); // Squared length of ray direction
    float h = dot(r.dir,oc);
    float c = dot(oc,oc) - rad*rad;
    float discriminant = h*h - a*c;

    if (discriminant<0.0){
        return -1.0;
    }else{
        return (h-sqrt(discriminant))/a;
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    mat4 camera = createCamMatrix(vec3(sin(iTime),0,2),vec3(0,0,-0.5),vec3(0,1,0));

    vec2 UV = (fragCoord-0.5*iResolution.xy)/iResolution.y;
    vec3 col = vec3(0.0);

    ray r = getCamRay(camera,UV);

    // Simple sphere example
    float dist = sphereIntersect(r,vec3(0.0),1.0);

    if (dist>0.0){
        vec3 pos = at(r,dist);
        vec3 norm = normalize(pos);
        col = texture(iChannel0,reflect(r.dir,norm)).rgb;
    }else{
        col = 0.5 + 0.5*r.dir;
    }

    fragColor = vec4(col,1.0);
}

struct ray{
    vec3 pos;
    vec3 dir;
};

// Returns the point at distance t along ray r
vec3 at(ray r,float t){
    return r.pos + r.dir*t;
}

mat4 createCamMatrix(vec3 pos,vec3 dir,vec3 up){
    vec3 right = normalize(cross(dir,up));
    up = normalize(cross(right,dir));
    return mat4(
        vec4(right,0.0),
        vec4(up,   0.0),
        vec4(dir,  0.0),
        vec4(pos,  1.0)
    );
}

ray getCamRay(mat4 cam,vec2 UV){
    return ray(cam[3].xyz,cam[0].xyz*UV.x+cam[1].xyz*UV.y+cam[2].xyz);
}

// Calculates near and far intersection between a ray and an AABB centered at the origin with a width of 1.0
// Useful for building scenes from boxes defined by mat4s (just transform the ray to local space and put it through this function) 
vec2 BoxIntersect(ray r){
    vec3 tMin = (-0.5-r.pos)/r.dir;
    vec3 tMax = ( 0.5-r.pos)/r.dir;
    vec3 t1 = min(tMin,tMax);
    vec3 t2 = max(tMin,tMax);
    return vec2(
        max(max(t1.x,t1.y),t1.z), // Near
        min(min(t2.x,t2.y),t2.z) // Far
    );
}

// Not used here, but handy if you need to do any refraction

struct refInfo{
    vec3 reflected;
    vec3 refracted;
    float refFac;
};

refInfo getRefInfo(vec3 dir, vec3 norm, float n1, float n2){
    vec3 refl = reflect(dir,norm);
    vec3 refr = refract(dir,norm,n1/n2);
    float incidence = dot(dir,-norm);
    float transmission = dot(refr,-norm);
    float refS = (n1*incidence - n2*transmission)/
                 (n1*incidence + n2*transmission);
    float refP = (n2*incidence - n1*transmission)/
                 (n2*incidence + n1*transmission);

    float ref = mix(refS*refS,refP*refP,0.5);

    return refInfo(refl,refr,ref);
}
